            "text": "اسم البلد لا يقول شيئاً عن ثلاثة أمور تقرّر ما ستذوقه: الدرجة المكتوبة على الملصق، وطزاجة الزيت أي كم مضى على عصره، وكيف عُومِلت الزجاجة من المعصرة إلى الرفّ. زجاجة أوروبية بقيت سنتين قرب نافذة أضعف من زجاجة شمال أفريقية عُصرت قبل شهرين وحُفظت في العتمة، والعكس صحيح تماماً."
